def apply_feedback_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["Review", "ReviewReport", "Question"]:
            schema_editor.create_model(apps.get_model("feedback", model_name))

def reverse_feedback_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["Question", "ReviewReport", "Review"]:
            schema_editor.delete_model(apps.get_model("feedback", model_name))

